enum DeliveryState: String, Codable { case sending, sent, delivered, read, failed }

struct Message: Identifiable, Codable, Sendable {
    let id: UUID                  // client generated, idempotency key
    let conversationID: String
    var sequence: Int64?          // assigned by server
    let senderID: String
    let body: Body                // .text / .media(ref, thumbnail)
    let sentAt: Date
    var state: DeliveryState
}

// socket frames
// -> {"type":"send","id":"<uuid>","conv":"c1","body":{...}}
// <- {"type":"ack","id":"<uuid>","seq":1042,"ts":...}
// <- {"type":"msg","conv":"c1","seq":1043,...}
// -> {"type":"read","conv":"c1","upTo":1043}
